-- psql -v retention_at='2026-10-21T00:00:00Z' -f retention/identity-secret-preview.sql
-- Counts only; parent deferral takes precedence over send deferral.
BEGIN READ ONLY;
SET LOCAL statement_timeout='10s';
WITH cutoff AS(SELECT :'retention_at'::timestamptz-interval '720 hours' AS at)
SELECT 'reset' AS family,count(*) FILTER(WHERE NOT(EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND o.state NOT IN('COMPLETED','REJECTED'))) AND NOT EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RESET' AND b.source_id=d.proof_id)) AS eligible_secrets,count(*) FILTER(WHERE NOT(EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND o.state NOT IN('COMPLETED','REJECTED'))) AND EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RESET' AND b.source_id=d.proof_id)) AS deferred_sends,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND o.state NOT IN('COMPLETED','REJECTED'))) AS deferred_operations FROM password_reset_delivery d JOIN password_reset_proof p ON p.id=d.proof_id CROSS JOIN cutoff c WHERE d.encrypted_token IS NOT NULL AND d.created_at<=c.at AND p.expires_at<=c.at
UNION ALL
SELECT 'email' AS family,count(*) FILTER(WHERE NOT(e.state='RECONCILING' OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND o.state NOT IN('COMPLETED','REJECTED'))) AND NOT EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='EMAIL_PROOF' AND b.source_id=d.proof_id)) AS eligible_secrets,count(*) FILTER(WHERE NOT(e.state='RECONCILING' OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND o.state NOT IN('COMPLETED','REJECTED'))) AND EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='EMAIL_PROOF' AND b.source_id=d.proof_id)) AS deferred_sends,count(*) FILTER(WHERE e.state='RECONCILING' OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND o.state NOT IN('COMPLETED','REJECTED'))) AS deferred_operations FROM email_change_delivery d JOIN email_change_proof p ON p.id=d.proof_id JOIN email_change e ON e.id=p.change_id CROSS JOIN cutoff c WHERE d.encrypted_token IS NOT NULL AND d.created_at<=c.at AND e.expires_at<=c.at
UNION ALL
SELECT 'setup' AS family,count(*) FILTER(WHERE NOT(EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=d.invitation_id AND t.state NOT IN('REJECTED','COMPLETED'))) AND NOT EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='SETUP' AND b.source_id=d.id)) AS eligible_secrets,count(*) FILTER(WHERE NOT(EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=d.invitation_id AND t.state NOT IN('REJECTED','COMPLETED'))) AND EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='SETUP' AND b.source_id=d.id)) AS deferred_sends,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=d.invitation_id AND t.state NOT IN('REJECTED','COMPLETED'))) AS deferred_operations FROM setup_delivery d JOIN setup_invitation i ON i.id=d.invitation_id LEFT JOIN setup_email_proof p ON p.id=d.proof_id CROSS JOIN cutoff c WHERE d.encrypted_token IS NOT NULL AND d.created_at<=c.at AND ((d.generation=i.generation AND i.expires_at<=c.at AND (d.proof_id IS NULL OR p.expires_at<=c.at)) OR(d.generation<i.generation AND d.created_at<=c.at-interval '168 hours'))
UNION ALL
SELECT 'recovery' AS family,count(*) FILTER(WHERE NOT(r.state='RECONCILING') AND NOT EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RECOVERY' AND b.source_id=d.id)) AS eligible_secrets,count(*) FILTER(WHERE NOT(r.state='RECONCILING') AND EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RECOVERY' AND b.source_id=d.id)) AS deferred_sends,count(*) FILTER(WHERE r.state='RECONCILING') AS deferred_operations FROM recovery_delivery d JOIN recovery_case r ON r.id=d.case_id CROSS JOIN cutoff c WHERE d.encrypted_token IS NOT NULL AND d.created_at<=c.at AND d.kind='ACCEPTANCE' AND r.expires_at<=c.at
ORDER BY family;
ROLLBACK;
